SELECT CASE WHEN humidity >= 83 THEN 'LARGE' ELSE 'SMALL' END AS humidity_tier, (UNIX_TIMESTAMP(MAX(reading_ts)) - UNIX_TIMESTAMP(MIN(reading_ts))) / 60 AS duration_min, ROUND(SUM(status_bits) / NULLIF(COUNT(CASE WHEN device_code = 'DV-04' THEN 1 END), 0), 2) AS status_bits_per_dv_04, SORT_ARRAY(COLLECT_SET(device_code)) AS device_code_list, SIZE(COLLECT_SET(device_code)) AS num_device_codes FROM device_readings GROUP BY humidity_tier;
